-- =====================================================================
-- MEDD-App — 030 Catálogo DANE de centros poblados (Sección 11, Cambio 2b · R10)
--
-- Fuente OFICIAL (verbatim, NO inventada): DANE DIVIPOLA — Códigos de cabeceras y
-- centros poblados (archivo aportado por el stakeholder, 2026-07-26; 8161
-- registros). Lleva R4 a la granularidad de CENTRO POBLADO (8 díg.) donde exista.
--
-- municipio_codigo enlaza con el municipio (022). NO se impone FK dura a
-- municipio_dane: los dos snapshots DANE pueden diferir levemente; se indexa para
-- el join analítico y se deja la validación de cobertura al monitoreo.
--
-- Idempotente: create table if not exists; on conflict do nothing (por lotes).
-- RLS de solo lectura. Rollback: drop table public.centro_poblado_dane.
-- =====================================================================

create table if not exists public.centro_poblado_dane (
  codigo           text primary key,     -- código DANE de centro poblado (8 díg.)
  nombre           text not null,
  municipio_codigo text,                 -- enlaza con municipio_dane(codigo) (022)
  departamento     text,
  tipo             text                  -- CM (cabecera) | CP (centro poblado)
);
create index if not exists idx_cp_dane_municipio on public.centro_poblado_dane(municipio_codigo);

alter table public.centro_poblado_dane enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where tablename='centro_poblado_dane' and policyname='cp_dane_read') then
    create policy cp_dane_read on public.centro_poblado_dane for select to authenticated using (true);
  end if;
end $$;

